covers.designs/uart/covers/R3.sv:
// Overrun: a second good frame lands while the first word (8'h3C) is still
// unread with m_axis_tready low; the output register now holds 8'hA5.
module cov_R3 (
  input logic       clk,
  input logic       rst,
  input logic       overrun_error,
  input logic       m_axis_tvalid,
  input logic       m_axis_tready,
  input logic [7:0] m_axis_tdata
);

  R3_overrun_second_word: cover property (@(posedge clk) disable iff (rst)
    overrun_error && m_axis_tvalid && (m_axis_tdata == 8'hA5) &&
    ($past(m_axis_tdata) == 8'h3C) && !$past(m_axis_tready));

endmodule

bind uart_rx cov_R3 u_cov_R3 (.*);

covers.designs/uart/covers/R4.sv:
// R4: receiver output held under back-pressure, then accepted.
module cov_R4 (
  input logic       clk,
  input logic       rst,
  input logic [7:0] m_axis_tdata,
  input logic       m_axis_tvalid,
  input logic       m_axis_tready,
  input logic       overrun_error
);

  logic [3:0] stall_cnt;
  logic [7:0] data_hold;

  always @(posedge clk) begin
    if (rst) begin
      stall_cnt <= 4'd0;
      data_hold <= 8'h00;
    end else begin
      data_hold <= m_axis_tdata;
      if (overrun_error) begin
        stall_cnt <= 4'd0;
      end else if (m_axis_tvalid && !m_axis_tready) begin
        if (stall_cnt != 4'd0 && m_axis_tdata != data_hold) begin
          stall_cnt <= 4'd1;
        end else if (stall_cnt != 4'd15) begin
          stall_cnt <= stall_cnt + 4'd1;
        end
      end else begin
        stall_cnt <= 4'd0;
      end
    end
  end

  R4_rx_backpressure_hold: cover property (@(posedge clk) disable iff (rst)
    m_axis_tvalid && m_axis_tready && !overrun_error &&
    stall_cnt >= 4'd4 && m_axis_tdata == data_hold && m_axis_tdata == 8'hA5);

endmodule

bind uart_rx cov_R4 u_cov_R4 (.*);

covers.designs/uart/covers/R5.sv:
module cov_R5 (
  input logic       clk,
  input logic       rst,
  input logic       busy,
  input logic       m_axis_tvalid,
  input logic [7:0] m_axis_tdata
);

  // 0: idle
  // 1: reset seen while busy with a pending word
  // 2: out of reset with tvalid and busy low
  reg [1:0] st;

  always @(posedge clk) begin
    if (rst) begin
      if (busy && m_axis_tvalid) st <= 2'd1;
      else if (st == 2'd2) st <= 2'd0;
    end else begin
      if (st == 2'd1 && !m_axis_tvalid && !busy) st <= 2'd2;
    end
  end

  R5_rst_mid_frame_pending: cover property (@(posedge clk)
    st == 2'd2 && !rst && m_axis_tvalid && m_axis_tdata == 8'hA5);

endmodule

bind uart_rx cov_R5 u_cov_R5 (.*);

covers.designs/uart/covers/R6.sv:
// Repeated frame errors during a line break: frame_error pulses at least
// twice while rxd stays low at every clock in between, with m_axis_tvalid low.

module cov_R6 (
  input logic clk,
  input logic rst,
  input logic rxd,
  input logic frame_error,
  input logic m_axis_tvalid
);

  // Number of frame_error pulses seen since rxd was last high (saturating).
  reg [1:0] fe_cnt;

  always @(posedge clk) begin
    if (rst) begin
      fe_cnt <= 2'd0;
    end else if (rxd) begin
      fe_cnt <= 2'd0;
    end else if (frame_error && fe_cnt != 2'd3) begin
      fe_cnt <= fe_cnt + 2'd1;
    end
  end

  R6_break_repeated_frame_error: cover property (@(posedge clk) disable iff (rst)
    frame_error && !rxd && (fe_cnt != 2'd0) && !m_axis_tvalid);

endmodule

bind uart_rx cov_R6 u_cov_R6 (.*);

covers.designs/uart/covers/R7.sv:
// Receive at maximum prescale: prescale_reg must hold the full 19-bit reload
// (0xFFFF << 3) - 1 = 19'h7FFF7, then a word 8'hA5 is delivered.
module cov_R7 (
  input logic        clk,
  input logic        rst,
  input logic [15:0] prescale,
  input logic [18:0] prescale_reg,
  input logic        m_axis_tvalid,
  input logic [7:0]  m_axis_tdata
);

  reg seen_full;

  always @(posedge clk) begin
    if (rst) begin
      seen_full <= 1'b0;
    end else begin
      if (prescale_reg == 19'h7FFF7) begin
        seen_full <= 1'b1;
      end
    end
  end

  R7_rx_max_prescale: cover property (@(posedge clk) disable iff (rst)
    seen_full && (prescale == 16'hFFFF) && $rose(m_axis_tvalid) && (m_axis_tdata == 8'hA5));

endmodule

bind uart_rx cov_R7 u_cov_R7 (.*);

covers.designs/uart/covers/R8.sv:
// Reset taken mid-frame after a word was delivered and handed off:
// the first reset edge must clear busy, tvalid and tdata.
module cov_R8 (
  input logic       clk,
  input logic       rst,
  input logic [7:0] m_axis_tdata,
  input logic       m_axis_tvalid,
  input logic       busy
);

  R8_reset_midframe_clears_outputs: cover property (@(posedge clk)
    rst && $past(rst) &&
    $past(busy) && !$past(m_axis_tvalid) && ($past(m_axis_tdata) == 8'hA5) &&
    !busy && !m_axis_tvalid && (m_axis_tdata == 8'h00));

endmodule

bind uart_rx cov_R8 u_cov_R8 (.*);

covers.designs/uart/covers/R9.sv:
// R9: reset taken mid-bit with rxd held low; the new start bit is picked up
// promptly, so busy is first seen high on the third clock after rst falls.
module cov_R9 (
  input logic        clk,
  input logic        rst,
  input logic        rxd,
  input logic        busy,
  input logic [18:0] prescale_reg
);

  reg       in_rst;
  reg       seen_mid;
  reg       rxd_low;
  reg       early;
  reg [1:0] cnt;

  always @(posedge clk) begin
    if (rst) begin
      in_rst <= 1'b1;
      cnt    <= 2'd0;
      early  <= 1'b0;
      if (!in_rst) begin
        seen_mid <= (prescale_reg > 19'd16) && !rxd;
        rxd_low  <= !rxd;
      end else begin
        if (rxd) rxd_low <= 1'b0;
      end
    end else begin
      in_rst <= 1'b0;
      if (cnt != 2'd3) cnt <= cnt + 2'd1;
      if (rxd) rxd_low <= 1'b0;
      if (busy && (cnt < 2'd2)) early <= 1'b1;
    end
  end

  R9_rx_reset_mid_frame_prompt_restart: cover property (@(posedge clk)
    !rst && (cnt == 2'd2) && busy && !early && seen_mid && rxd_low && !rxd);

endmodule

bind uart_rx cov_R9 u_cov_R9 (.*);

covers.designs/uart/covers/T1.sv:
// T1: reset taken while the transmitter drives a low bit mid-frame.
// On the next clock the line must be back at mark (txd = 1) and busy must be 0.
module cov_T1 (
  input logic clk,
  input logic rst,
  input logic txd,
  input logic busy
);

  T1_tx_reset_mid_frame_low: cover property (@(posedge clk)
    $past(rst) && !$past(txd) && $past(busy) && txd && !busy);

endmodule

bind uart_tx cov_T1 u_cov_T1 (.*);

covers.designs/uart/covers/T2.sv:
module cov_T2 (
  input logic        clk,
  input logic        rst,
  input logic [15:0] prescale,
  input logic [18:0] prescale_reg,
  input logic [3:0]  bit_cnt,
  input logic        txd,
  input logic        s_axis_tvalid,
  input logic [7:0]  s_axis_tdata
);

  reg [7:0] shift;
  reg       active;
  reg       done;

  always @(posedge clk) begin
    if (rst) begin
      shift  <= 8'h00;
      active <= 1'b0;
      done   <= 1'b0;
    end else begin
      done <= 1'b0;
      if (prescale_reg == 19'd0 && bit_cnt == 4'd0 && s_axis_tvalid) begin
        // a new frame is loaded on this edge
        active <= (prescale == 16'hFFFF);
        shift  <= 8'h00;
      end else if (active && prescale_reg == 19'd0 && bit_cnt != 4'd0 && bit_cnt <= 4'd8) begin
        // at a bit boundary txd still holds the data bit that is ending
        shift <= {txd, shift[7:1]};
        if (bit_cnt == 4'd1) begin
          done   <= 1'b1;
          active <= 1'b0;
        end
      end
      if (prescale != 16'hFFFF) begin
        active <= 1'b0;
      end
    end
  end

  T2_tx_max_prescale_5a: cover property (@(posedge clk) disable iff (rst)
    done && shift == 8'h5A && prescale_reg == 19'h7FFF8 && bit_cnt == 4'd0 &&
    txd && prescale == 16'hFFFF);

endmodule

bind uart_tx cov_T2 u_cov_T2 (.*);

covers.designs/uart/covers/T3.sv:
// T3: s_axis_tready, high while idle, is low on the 2nd and 3rd consecutive
// clocks of a held reset (baseline resets last only two clocks).
module cov_T3 (
  input logic clk,
  input logic rst,
  input logic s_axis_tready
);

  // 0: no tracking; 1: rst seen with tready high (idle);
  // 2: next rst clock had tready low; 3: saturated
  reg [1:0] cnt;

  always @(posedge clk) begin
    if (rst) begin
      if (cnt == 2'd0) begin
        if (s_axis_tready) cnt <= 2'd1;
      end else if (cnt != 2'd3) begin
        if (!s_axis_tready) cnt <= cnt + 2'd1;
        else cnt <= 2'd0;
      end
    end else begin
      cnt <= 2'd0;
    end
  end

  T3_tready_low_through_held_reset: cover property (@(posedge clk)
    rst && cnt == 2'd2 && !s_axis_tready);

endmodule

bind uart_tx cov_T3 u_cov_T3 (.*);

covers.designs/uart/covers/T4.sv:
// Reset applied mid-bit (prescale_reg > 16) must clear the prescaler so that
// s_axis_tready rises on the second clock after reset release.
module cov_T4 (
  input logic        clk,
  input logic        rst,
  input logic [18:0] prescale_reg,
  input logic        s_axis_tready
);

  logic       rst_q;
  logic       armed;
  logic [1:0] cnt;

  always @(posedge clk) begin
    rst_q <= rst;
    if (rst) begin
      cnt <= 2'd0;
      if (!rst_q) begin
        if (prescale_reg > 19'd16) armed <= 1'b1;
        else armed <= 1'b0;
      end else begin
        if (prescale_reg > 19'd16) armed <= 1'b1;
      end
    end else begin
      if (cnt != 2'd3) cnt <= cnt + 2'd1;
    end
  end

  T4_tx_reset_mid_frame_ready_timing: cover property (@(posedge clk)
    armed && !rst && cnt == 2'd1 && s_axis_tready && !$past(s_axis_tready));

endmodule

bind uart_tx cov_T4 u_cov_T4 (.*);

